class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def isPalindrome(self, head):
        self.front = head

        def check(node):
            if not node:
                return True
            if not check(node.next):
                return False
            same = self.front.val == node.val
            self.front = self.front.next
            return same

        return check(head)

